86: function exactSettlementRecord(value: unknown, keys: readonly string[]): Readonly<Record<string, unknown>> | undefined {
87: 	try {
88: 		if (value === null || typeof value !== "object" || Object.getPrototypeOf(value) !== Object.prototype) {
89: 			return undefined;
90: 		}
91: 		const actual = Reflect.ownKeys(value);
92: 		if (actual.length !== keys.length || actual.some((key) => typeof key !== "string" || !keys.includes(key))) {
93: 			return undefined;
94: 		}
95: 		const output = Object.create(null) as Record<string, unknown>;
96: 		for (const key of keys) {
97: 			const descriptor = Object.getOwnPropertyDescriptor(value, key);
98: 			if (descriptor === undefined || descriptor.enumerable !== true || !("value" in descriptor)) return undefined;
99: 			output[key] = descriptor.value;
100: 		}
101: 		return Object.freeze(output);
102: 	} catch {
103: 		return undefined;
104: 	}
105: }
