107: function exactSettlementArray(value: unknown): readonly unknown[] | undefined {
108: 	try {
109: 		if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype) return undefined;
110: 		const length = value.length;
111: 		if (!Number.isSafeInteger(length) || length < 0) return undefined;
112: 		const keys = Reflect.ownKeys(value);
113: 		if (keys.length !== length + 1 || keys[length] !== "length") return undefined;
114: 		for (let index = 0; index < length; index += 1) {
115: 			const key = String(index);
116: 			const descriptor = Object.getOwnPropertyDescriptor(value, key);
117: 			if (
118: 				keys[index] !== key ||
119: 				descriptor === undefined ||
120: 				descriptor.enumerable !== true ||
121: 				!("value" in descriptor)
122: 			) {
123: 				return undefined;
124: 			}
125: 		}
126: 		return value;
127: 	} catch {
128: 		return undefined;
129: 	}
